// stark planner main theme for stark_planner. Same mechanism as the kit's Teal preset:
// one main colour drives BOTH the accent tokens (buttons / links / focus / info)
// AND the top bar + command bar (nav-* tokens). Generated by new-service.mjs.
import { setTokenOverride } from 'lilak-ui'

export const STARKPLANNER = {
  "btn-primary-bg": "#2673c2",
  "btn-primary-hover": "#2062a5",
  "btn-primary-text": "#ffffff",
  "text-link": "#2673c2",
  "text-link-hover": "#2062a5",
  "border-focus": "#2673c2",
  "input-focus-border": "#2673c2",
  "info-bg": "#e1ebf6",
  "info-text": "#2062a5",
  "selection-bg": "rgba(38,115,194,0.28)",
  "nav-bg": "#2673c2",
  "nav-border": "#2165ab",
  "nav-accent": "#2165ab",
  "nav-text": "#ffffff",
  "nav-text-muted": "#bed5ed"
}

/** Apply the stark_planner colour overrides on top of the active base theme (call after applyTheme()). */
export function applyMainColor() {
  for (const [name, value] of Object.entries(STARKPLANNER)) setTokenOverride(name, value)
}

// Only 'bright' is offered — the main colour is fixed via overrides, so
// dark/lowcontrast barely differ. Add their ids back here to offer them.
export const ENABLED_THEMES = ['bright']
